function LivePrice(symbol) {
  $effect(() => {
    $quote = $http({ url: `https://api.example.com/price/${symbol}` })
  }, ["every(1000)"])

  return Card([
    SectionHeader(symbol),
    Text(`${$quote.data}`)
  ])
}

